PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, google_sub TEXT UNIQUE, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, handle TEXT UNIQUE COLLATE NOCASE, avatar TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','moderator','admin')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), adult_confirmed_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_states(state TEXT PRIMARY KEY,session_hash TEXT NOT NULL REFERENCES sessions(hash) ON DELETE CASCADE,verifier TEXT NOT NULL,nonce TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,history_enabled INTEGER NOT NULL DEFAULT 1,autoplay INTEGER NOT NULL DEFAULT 0,notify_uploads INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',links TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS videos(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('public','private','unlisted')),status TEXT NOT NULL CHECK(status IN ('queued','processing','ready','failed','removed')),source_path TEXT,media_path TEXT,thumbnail_path TEXT,source_hash TEXT NOT NULL,bytes INTEGER NOT NULL,duration REAL NOT NULL DEFAULT 0,width INTEGER,height INTEGER,comments_enabled INTEGER NOT NULL DEFAULT 1,error TEXT,created_at TEXT NOT NULL,published_at TEXT,UNIQUE(channel_id,source_hash));
CREATE TABLE IF NOT EXISTS processing_jobs(id TEXT PRIMARY KEY,video_id TEXT NOT NULL UNIQUE REFERENCES videos(id) ON DELETE CASCADE,attempts INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'queued',error TEXT,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,channel_id TEXT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,created_at TEXT NOT NULL,PRIMARY KEY(user_id,channel_id));
CREATE TABLE IF NOT EXISTS reactions(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,value INTEGER NOT NULL CHECK(value IN (-1,1)),PRIMARY KEY(user_id,video_id));
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY,video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,parent_id TEXT REFERENCES comments(id) ON DELETE CASCADE,body TEXT NOT NULL,pinned INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'visible',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS video_views(id TEXT PRIMARY KEY,video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,day TEXT NOT NULL,watch_seconds REAL NOT NULL DEFAULT 0,created_at TEXT NOT NULL,UNIQUE(video_id,user_id,day));
CREATE TABLE IF NOT EXISTS history(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,seconds REAL NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,video_id));
CREATE TABLE IF NOT EXISTS leaves(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,body TEXT NOT NULL,video_id TEXT REFERENCES videos(id) ON DELETE SET NULL,parent_id TEXT REFERENCES leaves(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'visible',created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE IF NOT EXISTS leaf_likes(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,leaf_id TEXT NOT NULL REFERENCES leaves(id) ON DELETE CASCADE,PRIMARY KEY(user_id,leaf_id));
CREATE TABLE IF NOT EXISTS leaf_reposts(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,leaf_id TEXT NOT NULL REFERENCES leaves(id) ON DELETE CASCADE,PRIMARY KEY(user_id,leaf_id));
CREATE TABLE IF NOT EXISTS playlists(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS playlist_items(id TEXT PRIMARY KEY,playlist_id TEXT NOT NULL REFERENCES playlists(id) ON DELETE CASCADE,video_id TEXT REFERENCES videos(id) ON DELETE CASCADE,leaf_id TEXT REFERENCES leaves(id) ON DELETE CASCADE,created_at TEXT NOT NULL,CHECK((video_id IS NOT NULL)+(leaf_id IS NOT NULL)=1),UNIQUE(playlist_id,video_id),UNIQUE(playlist_id,leaf_id));
CREATE TABLE IF NOT EXISTS stories(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,caption TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN ('image','video')),media_path TEXT NOT NULL,bytes INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'visible',created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS blocks(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,blocked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL,PRIMARY KEY(user_id,blocked_id),CHECK(user_id<>blocked_id));
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,reason TEXT NOT NULL,details TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notes(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,body TEXT NOT NULL,sources TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','removed')),created_at TEXT NOT NULL,UNIQUE(user_id,target_type,target_id));
CREATE TABLE IF NOT EXISTS note_ratings(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,note_id TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,helpful INTEGER NOT NULL CHECK(helpful IN (0,1)),created_at TEXT NOT NULL,PRIMARY KEY(user_id,note_id));
CREATE TABLE IF NOT EXISTS moderation_actions(id TEXT PRIMARY KEY,moderator_id TEXT REFERENCES users(id) ON DELETE SET NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,action TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS appeals(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,action_id TEXT NOT NULL REFERENCES moderation_actions(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,body TEXT NOT NULL,url TEXT NOT NULL DEFAULT '/',read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,hits INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS videos_feed ON videos(status,visibility,published_at DESC);
CREATE INDEX IF NOT EXISTS videos_channel ON videos(channel_id,created_at DESC);
CREATE INDEX IF NOT EXISTS comments_video ON comments(video_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS leaves_feed ON leaves(status,parent_id,created_at DESC);
CREATE INDEX IF NOT EXISTS stories_expiration ON stories(expires_at,status);
CREATE INDEX IF NOT EXISTS reports_queue ON reports(status,created_at);
CREATE INDEX IF NOT EXISTS sessions_expiration ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS views_video ON video_views(video_id,day);
CREATE INDEX IF NOT EXISTS subscriptions_channel ON subscriptions(channel_id);
INSERT OR IGNORE INTO schema_migrations VALUES(1,datetime('now'));
